/* [rule=font-size] [selector=ypyp-sym-tsymyp-sym-tcsubmit] [msize=desktop] */
 #submit{font-size:15px} 
/* [rule=text-transform] [selector=ypyp-sym-tsymyp-sym-tcsubmit] [msize=desktop] */
 #submit{text-transform:capitalize} 
/* [rule=font-weight] [selector=yp-sym-ublogyp-sym-tsingleyp-sym-tdetailsyp-sym-ublogyp-sym-tsingleyp-sym-theaderh1] [msize=desktop] */
 .blog-single-details .blog-single-header h1{font-weight:600} 
/* [rule=text-transform] [selector=yp-sym-ublogyp-sym-tsingleyp-sym-tdetailsyp-sym-ublogyp-sym-tsingleyp-sym-theaderh1] [msize=desktop] */
 .blog-single-details .blog-single-header h1{text-transform:capitalize} 
/* [rule=font-family] [selector=ypyp-sym-tsymyp-sym-tcwrapypyp-sym-tsymyp-sym-tccontentyp-sym-ucontaineryp-sym-urowyp-sym-ucontentsyp-sym-tcontaineryp-sym-ublogyp-sym-tsingleyp-sym-uentryyp-sym-tcontentyp-sym-ublogyp-sym-tsingleyp-sym-tdetailsyp-sym-ublogyp-sym-tsingleyp-sym-theaderh1] [msize=desktop] */
 #wrap #content .container .row .contents-container .blog-single .entry-content .blog-single-details .blog-single-header h1{font-family:'Poppins', sans-serif !important} 
/* [rule=font-family] [selector=ypyp-sym-tsymyp-sym-tcwrapypyp-sym-tsymyp-sym-tccontentyp-sym-ucontaineryp-sym-urowyp-sym-ucontentsyp-sym-tcontaineryp-sym-ublogyp-sym-tsingleyp-sym-uentryyp-sym-tcontentpspan] [msize=desktop] */
 #wrap #content .container .row .contents-container .blog-single .entry-content p span{font-family:'Poppins', sans-serif !important} 
/* [rule=padding-left] [selector=ypyp-sym-tsymyp-sym-tcwrapyp-sym-ublogyp-sym-tsingleyp-sym-uentryyp-sym-tcontent] [msize=(min-width:1200px)] */
 @media (min-width:1200px){#wrap .blog-single .entry-content{padding-left:100px}} 
/* [rule=padding-right] [selector=ypyp-sym-tsymyp-sym-tcwrapyp-sym-ublogyp-sym-tsingleyp-sym-uentryyp-sym-tcontent] [msize=(min-width:1200px)] */
 @media (min-width:1200px){#wrap .blog-single .entry-content{padding-right:102px}}
